theme.css:
#wemd{color:#1a1a1a;background-color:#ffffff;font-family:-apple-system, 'PingFang SC', 'Segoe UI', 'Noto Sans SC', sans-serif;font-size:16px;line-height:1.8;letter-spacing:0em;text-align:justify;padding:32px 24px;overflow-wrap:anywhere}
#wemd p{margin:0 0 1.2em;text-indent:0}
#wemd h1{font-size:28px;font-weight:800;color:$colors.text_primary;margin-top:2em;margin-bottom:1em;text-align:left}
#wemd h2{font-size:22px;font-weight:700;color:$colors.text_primary;margin-top:1.8em;margin-bottom:0.8em;text-align:left;border-bottom:1px solid $colors.accent;padding-bottom:.4em}
#wemd h3{font-size:18px;font-weight:600;color:$colors.accent;margin-top:1.5em;margin-bottom:0.6em}
#wemd h4{font-size:16px;font-weight:600;color:$colors.text_secondary;margin-top:1.2em;margin-bottom:0.5em}
#wemd blockquote{border-left:4px solid $colors.quote_border;background:$colors.quote_background;padding:14px 20px;color:$colors.text_secondary;font-style:normal;margin:1.2em 0}
#wemd code{background-color:$colors.code_background;color:#da2c1f;padding:2px 6px;border-radius:4px;font-size:0.9em;font-family:'JetBrains Mono', 'Fira Code', monospace}
#wemd pre{background:#1e1e1e;border-radius:8px;padding:18px 22px;line-height:1.6;white-space:pre-wrap}
#wemd pre code{background:transparent;padding:0}
#wemd table{width:100%;border-collapse:collapse}
#wemd th, #wemd td{border:1px solid $colors.border;padding:10px 14px}
#wemd th{background:$colors.table_header_bg}
#wemd tr:nth-child(even){background:$colors.table_stripe_bg}
#wemd ul, #wemd ol{padding-left:24px;margin:1em 0}
#wemd ul{list-style-type:disc}
#wemd ol{list-style-type:decimal}
#wemd li{margin-bottom:6px}
#wemd li::marker{color:$colors.accent}
#wemd hr{border:0;border-top:1px solid $colors.accent;margin:2em 0;width:30%}
#wemd img{max-width:100%;height:auto;border-radius:8px}
#wemd figcaption{font-size:13px;color:$colors.text_secondary;text-align:center}
#wemd a{color:$colors.link_color;text-decoration:none}
#wemd strong{color:#da2c1f;font-weight:700}
#wemd mark{background:$colors.highlight_bg;padding:2px 6px;border-radius:4px}
